#include <stdio.h>

static int leaves(int n)
{
    if (n <= 1) {
        return 1;
    }
    return leaves(n / 2) + leaves(n - n / 2);
}

int main(void)
{
    printf("%d\n", leaves(5));
    return 0;
}

#include <stdio.h>


int main(void)
{
    int calls = 1;
    for (int n = 8; n > 1; n /= 2) {
        calls++;
    }
    printf("%d\n", calls);
    return 0;
}

#include <stdio.h>


int main(void)
{
    int cost = 1;
    for (int n = 2; n <= 8; n *= 2) {
        cost = 2 * cost + n;
    }
    printf("%d\n", cost);
    return 0;
}
